import { nghiemThuEndpoint } from './endpoint';
import type { CreateNghiemThuRequest, UpdateNghiemThuRequest } from './requestModel';
import {
  FALLBACK_INIT_DATA,
  type NghiemThuInitDataDto,
  type NghiemThuPagedResult,
} from './responseModel';

export const nghiemThuService = {
  getList: (params?: {
    search?: string;
    status?: string;
    route?: string;
    templateType?: string;
    fromDate?: string;
    toDate?: string;
    page?: number;
    pageSize?: number;
  }): Promise<NghiemThuPagedResult> => nghiemThuEndpoint.getList(params),

  getInitData: async (): Promise<NghiemThuInitDataDto> => {
    try {
      const data = await nghiemThuEndpoint.getInitData();
      return {
        statuses: data?.statuses?.length ? data.statuses : FALLBACK_INIT_DATA.statuses,
        templateTypes: data?.templateTypes?.length
          ? data.templateTypes
          : FALLBACK_INIT_DATA.templateTypes,
      };
    } catch {
      return FALLBACK_INIT_DATA;
    }
  },

  getById: (id: string) => nghiemThuEndpoint.getById(id),

  create: (data: CreateNghiemThuRequest) => nghiemThuEndpoint.create(data),

  update: (id: string, data: UpdateNghiemThuRequest) => nghiemThuEndpoint.update(id, data),

  delete: (id: string) => nghiemThuEndpoint.delete(id),
};
