import { useCallback, useEffect, useMemo, useState } from 'react';
import type { CatalogUiSchema } from '@linm-soft-org/linm-web-common-components';
import { catalogUiSchemaService } from '../services/catalogUiSchema/catalogUiSchemaService';
import type { RmmsCatalogUiSchema } from '../utils/bootstrapCatalogUiSchema';

/**
 * Load catalog UI schema for list display.
 * Does **not** auto-PUT — first Save in LinCatalogUiSchemaEditorModal creates override
 * when `hasSavedOverride` is false (seed-only GET still shows full config grid).
 */
export function useCatalogUiSchema(
  catalogKind: string,
): {
  schema: RmmsCatalogUiSchema | null;
  loading: boolean;
  error: string | null;
  reload: () => void;
} {
  const [schema, setSchema] = useState<RmmsCatalogUiSchema | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);

  const reload = useCallback(() => {
    setReloadKey((k) => k + 1);
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    const t = window.setTimeout(() => {
      void (async () => {
        try {
          const data = (await catalogUiSchemaService.get(
            catalogKind,
            false,
          )) as RmmsCatalogUiSchema;
          if (!cancelled) setSchema(data);
        } catch (err) {
          if (!cancelled) {
            setError(
              err instanceof Error ? err.message : 'Lỗi tải cấu hình danh mục',
            );
            setSchema(null);
          }
        } finally {
          if (!cancelled) setLoading(false);
        }
      })();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [catalogKind, reloadKey]);

  useEffect(() => {
    const onCompanyChanged = () => setReloadKey((k) => k + 1);
    window.addEventListener('linm:company:changed', onCompanyChanged);
    return () =>
      window.removeEventListener('linm:company:changed', onCompanyChanged);
  }, []);

  return useMemo(
    () => ({ schema, loading, error, reload }),
    [schema, loading, error, reload],
  );
}

export type { CatalogUiSchema };
