/**
 * T-PERM-01 — patrol.nghiem-thu.read|write (Auth stub / local mode).
 */
import { isPermissionsLocalModeActive } from '../../dev/isPermissionsLocalMode';

export const NGHIEM_THU_PERMS = {
  read: 'patrol.nghiem-thu.read',
  create: 'patrol.nghiem-thu.write',
  update: 'patrol.nghiem-thu.write',
  delete: 'patrol.nghiem-thu.write',
} as const;

export type NghiemThuPermCode = (typeof NGHIEM_THU_PERMS)[keyof typeof NGHIEM_THU_PERMS];

export function hasNghiemThuPermission(code: NghiemThuPermCode): boolean {
  if (isPermissionsLocalModeActive()) return true;
  const bag = (window as unknown as { __LINM_PERMS__?: Record<string, boolean> })
    .__LINM_PERMS__;
  if (!bag) return true;
  return bag[code] === true;
}

export function nghiemThuListPermissions() {
  return {
    canRead: hasNghiemThuPermission(NGHIEM_THU_PERMS.read),
    canCreate: hasNghiemThuPermission(NGHIEM_THU_PERMS.create),
    canUpdate: hasNghiemThuPermission(NGHIEM_THU_PERMS.update),
    canDelete: hasNghiemThuPermission(NGHIEM_THU_PERMS.delete),
  };
}
